// What every open API address is for, in both languages.
//
// The addresses, their fields and what they need come from the code itself
// (routes.ts reads them); this file adds the one thing the code cannot say:
// a sentence for a person. A test fails when an address has no sentence here
// and is not listed as internal, so the reference stays complete.

export type Pair = [en: string, tr: string];

export interface Group {
  /** The page is docs/site/<lang>/ref-<id>.md. */
  id: string;
  title: Pair;
  summary: Pair;
  intro: Pair;
  /** "METHOD /path" → what it does. In the order they are shown. */
  routes: [key: string, en: string, tr: string][];
}

